import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.Crpw6aS5.js";const i=JSON.parse('{"title":"2016年 · 十年赌局获胜","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2016年.md","filePath":"05_quotes/by-year/2016年.md"}'),r={name:"05_quotes/by-year/2016年.md"};function s(c,e,u,h,_,q){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_2016年-·-十年赌局获胜" tabindex="-1">2016年 · 十年赌局获胜 <a class="header-anchor" href="#_2016年-·-十年赌局获胜" aria-label="Permalink to &quot;2016年 · 十年赌局获胜&quot;">​</a></h1><blockquote><p>如果竖立一座雕像来表彰为美国投资者做出最大贡献的人，毫无疑问应该选择杰克·博格尔。几十年来，杰克一直敦促投资者投资超低成本的指数基金。他是他们的英雄，也是我的英雄。——巴菲特（86岁）</p></blockquote><p>本页收录2016年致股东信中的经典语录。本年以巴菲特十年赌局胜利为核心事件，系统论证了主动投资管理的失败与指数基金的优势。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>表现来了又去。费用却永不动摇。</p></blockquote><blockquote><p>当一个有钱的人遇到一个有经验的人，有经验的人最终会得到钱，有钱的人会带着经验离开。</p></blockquote><blockquote><p>普遍恐惧是投资者的朋友，因为它提供了便宜的买入机会。个人恐惧是你的敌人。它也是没有根据的。</p></blockquote><blockquote><p>回购只有在以低于内在价值的价格购买股票时才有意义。令人费解的是，企业回购公告几乎从不提及一个价格上限。</p></blockquote><blockquote><p>我的建议：在讨论回购之前，CEO及其董事会应该站起来，手拉手，异口同声地声明：&quot;在一个价格上明智的做法，在另一个价格上是愚蠢的。&quot;</p></blockquote><blockquote><p>大约每十年左右，乌云会布满经济天空，它们会短暂地下起金雨。当这种倾盆大雨发生时，我们必须拿着洗衣盆而不是茶匙冲到户外。我们一定会这样做。</p></blockquote><blockquote><p>如今我宁愿做结肠镜检查的准备，也不愿发行伯克希尔股票。</p></blockquote><blockquote><p>我的计算，非常粗略，是精英对优越投资建议的寻找导致他们在过去十年总共浪费了超过1000亿美元。算一算：即使对数万亿美元收取1%的费用也会累积起来。</p></blockquote><blockquote><p>查理和我从不关注当前季度的业绩。事实上，伯克希尔可能是财富500强中唯一不编制月度收益报告或资产负债表的公司。</p></blockquote><blockquote><p>我坚信伯克希尔拥有资金、人才和文化来克服我上面列举的逆境——并以更大盈利能力脱颖而出。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2016年伯克希尔每股账面价值增长10.7%，股价上涨23.4%，均跑赢标普500的12.0%。巴菲特于2007年发起的十年赌局在第九年已基本锁定胜局——标普500指数基金累计收益85.4%，远超五只对冲基金组合的最高62.8%。浮存金突破910亿美元。本年也是巴菲特告别以账面价值作为主要业绩指标的起点。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2016年-翻译-·-01-letters-2016年-核心总结-·-01-letters-2016年-思维导图" tabindex="-1"><a href="/01_letters/2016年/翻译.html">01_letters/2016年/翻译</a> · <a href="/01_letters/2016年/核心总结.html">01_letters/2016年/核心总结</a> · <a href="/01_letters/2016年/思维导图.html">01_letters/2016年/思维导图</a> <a class="header-anchor" href="#_01-letters-2016年-翻译-·-01-letters-2016年-核心总结-·-01-letters-2016年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2016年/翻译]] · [[→ 核心总结|01_letters/2016年/核心总结]] · [[→ 思维导图|01_letters/2016年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2016年/翻译.html">/01_letters/2016年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",s]]);export{i as __pageData,p as default};
